  "inlineSchema": "datasource db {\n  provider = \"sqlite\"\n  url      = \"file:./dev.db\"\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated\"\n}\n\n/// Utilisateur de la plateforme (login/password)\n\nmodel User {\n  id        String   @id @default(uuid())\n  createdAt DateTime @default(now())\n\n  // Channels créés, memberships et actions\n  ownedChannels     Channel[]   @relation(\"ChannelOwner\")\n  guestChannels     Channel[]   @relation(\"ChannelGuest\")\n  magicLinksCreated MagicLink[] @relation(\"MagicLinkCreator\")\n  magicLinksUsed    MagicLink[] @relation(\"MagicLinkTarget\")\n  messagesSent      Message[]\n  filesUploaded     File[]\n  fileKeys          FileKey[]\n  email             String\n  emailVerified     Boolean\n  image             String?\n  updatedAt         DateTime\n  displayUsername   String?\n  sessions          Session[]\n  accounts          Account[]\n\n  name String\n\n  @@map(\"user\")\n}\n\n/// Lien magique à usage unique donnant le droit de créer un canal sécurisé\n\nmodel MagicLink {\n  id        Int      @id @default(autoincrement())\n  token     String   @unique\n  createdAt DateTime @default(now())\n  expiresAt DateTime\n  used      Boolean  @default(false)\n\n  // Créateur du lien\n  createdBy   User   @relation(\"MagicLinkCreator\", fields: [createdById], references: [id])\n  createdById String\n\n  // Utilisateur destinataire qui réclamera le canal\n  targetUser   User   @relation(\"MagicLinkTarget\", fields: [targetUserId], references: [id])\n  targetUserId String\n\n  // Canal créé lors de l'utilisation du lien\n  channel   Channel? @relation(fields: [channelId], references: [id])\n  channelId Int?     @unique\n}\n\n/// Salon de discussion / canal E2E (direct messaging only)\n\nmodel Channel {\n  id        Int      @id @default(autoincrement())\n  createdAt DateTime @default(now())\n\n  // Owner of the channel\n  owner   User   @relation(\"ChannelOwner\", fields: [ownerId], references: [id])\n  ownerId String\n\n  // Guest user in the channel\n  guest   User   @relation(\"ChannelGuest\", fields: [guestId], references: [id])\n  guestId String\n\n  // Messages et fichiers\n  messages Message[]\n  files    File[]\n\n  // MagicLink unique lié à ce canal\n  magicLink MagicLink?\n\n  @@unique([ownerId, guestId])\n}\n\n/// Messages chiffrés échangés dans un canal\n\nmodel Message {\n  id        Int     @id @default(autoincrement())\n  channel   Channel @relation(fields: [channelId], references: [id])\n  channelId Int\n  sender    User    @relation(fields: [senderId], references: [id])\n  senderId  String\n\n  encryptedContent String // Blob chiffré (Base64 ou binaire)\n  createdAt        DateTime @default(now())\n}\n\n/// Fichiers chiffrés envoyés dans un canal\n\nmodel File {\n  id         Int     @id @default(autoincrement())\n  channel    Channel @relation(fields: [channelId], references: [id])\n  channelId  Int\n  uploader   User    @relation(fields: [uploaderId], references: [id])\n  uploaderId String\n\n  filename  String // Nom original du fichier\n  url       String // URL ou chemin vers le blob chiffré\n  size      Int // Taille du fichier en octets\n  mimeType  String // Type MIME du fichier (image/png, application/pdf, etc.)\n  createdAt DateTime @default(now())\n\n  // Clés symétriques chiffrées pour chaque destinataire\n  fileKeys FileKey[]\n}\n\n/// Clés symétriques (AES) chiffrées avec la clé publique de chaque utilisateur\n\nmodel FileKey {\n  id           Int    @id @default(autoincrement())\n  file         File   @relation(fields: [fileId], references: [id])\n  fileId       Int\n  user         User   @relation(fields: [userId], references: [id])\n  userId       String\n  encryptedKey String // Clé AES chiffrée (Base64)\n\n  @@unique([fileId, userId])\n}\n\nmodel Session {\n  id        String   @id\n  expiresAt DateTime\n  token     String\n  createdAt DateTime\n  updatedAt DateTime\n  ipAddress String?\n  userAgent String?\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([token])\n  @@map(\"session\")\n}\n\nmodel Account {\n  id                    String    @id\n  accountId             String\n  providerId            String\n  userId                String\n  user                  User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  accessToken           String?\n  refreshToken          String?\n  idToken               String?\n  accessTokenExpiresAt  DateTime?\n  refreshTokenExpiresAt DateTime?\n  scope                 String?\n  password              String?\n  createdAt             DateTime\n  updatedAt             DateTime\n\n  @@map(\"account\")\n}\n\nmodel Verification {\n  id         String    @id\n  identifier String\n  value      String\n  expiresAt  DateTime\n  createdAt  DateTime?\n  updatedAt  DateTime?\n\n  @@map(\"verification\")\n}\n",
